#!/usr/bin/env python
# -*- coding: utf-8 -*-

"""Comprehensive test for the pdftk/qpdf fix"""

import sys
import os
sys.path.insert(0, os.path.join(os.path.dirname(__file__), '.'))

from paper2remarkable.utils import check_pdftool
from paper2remarkable.exceptions import NoPDFToolError

def test_both_tools_available():
    """Test when both tools are available (or mocked as available)"""
    print("Testing when both tools are available...")
    try:
        # Using "echo" for both since it's always available and returns 0
        result = check_pdftool("echo", "echo")  
        print(f"Result: {result}")
        # Should return pdftk since it's checked first
        if result == "pdftk":
            print("SUCCESS: Correctly chose pdftk (first preference)")
        else:
            print(f"NOTE: Got {result} (might be environment dependent)")
    except Exception as e:
        print(f"ERROR: {type(e).__name__}: {e}")

def test_pdftk_missing_qpdf_available():
    """Test when pdftk is missing but qpdf is available"""
    print("\nTesting when pdftk is missing but qpdf is available...")
    try:
        result = check_pdftool("nonexistent_pdftk", "echo")  # echo always succeeds
        print(f"Result: {result}")
        if result == "qpdf":
            print("SUCCESS: Correctly fell back to qpdf")
        else:
            print(f"UNEXPECTED: Got {result}")
    except Exception as e:
        print(f"ERROR: {type(e).__name__}: {e}")

def test_qpdf_missing_pdftk_available():
    """Test when qpdf is missing but pdftk is available"""
    print("\nTesting when qpdf is missing but pdftk is available...")
    try:
        result = check_pdftool("echo", "nonexistent_qpdf")  # echo succeeds, fake qpdf fails
        print(f"Result: {result}")
        if result == "pdftk":
            print("SUCCESS: Correctly chose pdftk")
        else:
            print(f"UNEXPECTED: Got {result}")
    except Exception as e:
        print(f"ERROR: {type(e).__name__}: {e}")

def test_both_tools_missing():
    """Test when both tools are missing"""
    print("\nTesting when both tools are missing...")
    try:
        result = check_pdftool("nonexistent_pdftk", "nonexistent_qpdf")
        print(f"UNEXPECTED: Got result {result}")
    except NoPDFToolError:
        print("SUCCESS: Correctly raised NoPDFToolError")
    except Exception as e:
        print(f"ERROR: {type(e).__name__}: {e}")

def test_none_values():
    """Test with None values"""
    print("\nTesting with None values...")
    try:
        result = check_pdftool(None, None)
        print(f"UNEXPECTED: Got result {result}")
    except NoPDFToolError:
        print("SUCCESS: Correctly raised NoPDFToolError for None values")
    except Exception as e:
        print(f"ERROR: {type(e).__name__}: {e}")

if __name__ == "__main__":
    test_both_tools_available()
    test_pdftk_missing_qpdf_available()
    test_qpdf_missing_pdftk_available()
    test_both_tools_missing()
    test_none_values()
    print("\nAll tests completed!")

